223	    public static void delayTransaction() {
224	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
225	        long startTime = System.nanoTime();
226	        long elapsedTime = System.nanoTime() - startTime;
227	
228	        if (useExponentialBackoff) {
229	            double r = gen.nextDouble() + 0.5; // Random number between 0.5 and 1.5
230	            long waitNanoseconds = (long) ((1L << (ftr.getRetries() + machineConstant)) * r);
231	            
232	            while (elapsedTime < waitNanoseconds) {
233	                elapsedTime = System.nanoTime() - startTime;
234	            }
235	        }
236	        
237	        ftr.incElapsedTime(elapsedTime);
238	        ftr.incRetries();
239	    }
