287	     * and the block starts again: an abort that names it, the abort() of a program, which names none
288	     * and is taken by the innermost block, or any abort that reaches the outermost block.  It throws
289	     * on an abort that names an ancestor, whose block starts again, and any other exception, which
290	     * leaves the block; a nested transaction first hands the reads on which that exception was thrown
291	     * to its parent (Transaction.TXLeave).
292	     */
293	    public static void leaveTransaction(Throwable t) {
294	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
295	        BaseTask currentTask = ftr.getTask();
296	        Transaction transaction = currentTask.transaction();
297	        if (debug) debug("Leave transaction ftr = " + ftr + " current action = " + currentTask + " trans = " + transaction + " on " + t);
298	        if (transaction == null)
299	            BaseTask.<RuntimeException>throwOn(t);
300	        currentTask.setTransaction(transaction.getParent());
301	        if (!(t instanceof TransactionAbortException)) {
302	            try {
303	                transaction.TXLeave();
304	            } catch (TransactionAbortException stale) {
305	                t = stale;
306	            }
307	        }
308	        if (t instanceof TransactionAbortException) {
309	            Transaction named = ((TransactionAbortException) t).transaction();
310	            if (named == null || named == transaction || transaction.getParent() == null)
311	                return;
312	        }
313	        BaseTask.<RuntimeException>throwOn(t);
314	    }
315	
316	    /** Throws t as it is, checked or not, as generated code throws. */
317	    @SuppressWarnings("unchecked")
318	    private static <T extends Throwable> void throwOn(Throwable t) throws T {
319	        throw (T) t;
320	    }
321	}

