 13	
 14	/**
 15	 * Abandons a transaction: the atomic block that began it discards its writes and starts again.
 16	 * A failed validation names the transaction whose read failed, which can be an ancestor of the one
 17	 * that found it; a block's handler starts only its own transaction again and passes any other
 18	 * abort outward.  The abort() of a program names none, and the innermost block takes it.
 19	 */
 20	public class TransactionAbortException extends RuntimeException {
 21	
 22	    private final Transaction transaction;
 23	
 24	    public TransactionAbortException() {
 25	        this.transaction = null;
 26	    }
 27	
 28	    public TransactionAbortException(Transaction transaction) {
 29	        this.transaction = transaction;
 30	    }
 31	
 32	    /**
 33	     * The copy that the join of a task makes on the joining thread, with the task's exception as
 34	     * its cause (java.util.concurrent.ForkJoinTask): it names the transaction that the cause names.
 35	     */
 36	    public TransactionAbortException(Throwable cause) {
 37	        super(cause);
 38	        this.transaction = (cause instanceof TransactionAbortException)
 39	            ? ((TransactionAbortException) cause).transaction : null;
 40	    }
 41	
 42	    /** The transaction to start again, or null for the innermost one. */
 43	    public Transaction transaction() {
 44	        return transaction;
 45	    }
 46	}
