 21	import com.sun.fortress.compiler.runtimeValues.MutableFValue;
 22	import com.sun.fortress.compiler.runtimeValues.RTTI;
 23	import fortress.AnyType.Any;
 24	
 25	public class Transaction {
 26	
 27	    /**
 28	     * A location that a transaction reads and writes: a cell, the MutableFValue of a mutable variable,
 29	     * or a Slot, one element of the Object[] of a compiled array store.  The read and write sets key
 30	     * both kinds; a slot is its array and its index.
 31	     */
 32	    static final class Slot {
 33	        private static final VarHandle ELEMENT = MethodHandles.arrayElementVarHandle(Object[].class);
 34	
 35	        final Object[] array;
 36	        final int index;
 37	
 38	        Slot(Object[] array, int index) {
 39	            this.array = array;
 40	            this.index = index;
 41	        }
 42	
 43	        /** The element, read with the memory semantics of a cell's volatile value. */
 44	        Any getValue() {
 45	            return (Any) ELEMENT.getVolatile(array, index);
 46	        }
 47	
 48	        void setValue(Any v) {
 49	            ELEMENT.setVolatile(array, index, v);
 50	        }
 51	
 52	        public boolean equals(Object o) {
 53	            return o instanceof Slot && ((Slot) o).array == array && ((Slot) o).index == index;
 54	        }
 55	
 56	        public int hashCode() {
 57	            return System.identityHashCode(array) * 31 + index;
 58	        }
 59	
 60	        public String toString() {
 61	            return "Slot " + index + " of array@" + Integer.toHexString(System.identityHashCode(array));
 62	        }
 63	    }
 64	
 65	    /** The committed value of a location, a cell or a slot. */
 66	    private static Any committedValue(Object location) {
 67	        if (location instanceof Slot) return ((Slot) location).getValue();
 68	        return ((MutableFValue) location).getValue();
 69	    }
 70	
 71	    private static void commitValue(Object location, Any v) {
 72	        if (location instanceof Slot) ((Slot) location).setValue(v);
 73	        else ((MutableFValue) location).setValue(v);
 74	    }
 75	
 76	    /** What a read set holds for the read of an element that held nothing, since it holds no null. */
 77	    private static final Any EMPTY = new Any() {
 78	        public RTTI getRTTI() { return null; }
 79	        public String toString() { return "an empty element"; }
 80	    };
 81	
 82	    private Transaction parent;
 83	    private static AtomicInteger global_lock = new AtomicInteger(0);
 84	    private AtomicInteger snapshot;
 85	    Hashtable<Object, Any> reads;
 86	    Hashtable<Object, Any> writes;
 87	    private Transaction topLevelTransaction;
 88	    private static boolean debug = false;
 89	    private static AtomicInteger counter = new AtomicInteger(0);
 90	    private int transactionNumber;
 91	
 92	    private String ancestrialString() {
 93	        Transaction current = this;
 94	        Stack transactionHistory = new Stack();
 95	        while (current != null) {
 96	            transactionHistory.push(current.transactionNumber);
 97	            current = current.parent;
 98	        }
 99	
100	        String result = "";
101	        Boolean first = true;
102	        while (!transactionHistory.empty()) {
103	            if (first) {
104	                result = result + transactionHistory.pop();
105	                first = false;
106	            } else {
107	                result = result +  ":=>" + transactionHistory.pop();
108	            }
109	        }
110	        return result;
111	    }
112	        
113	
114	    private void debug(String s) {
115	        if (debug)
116	            System.out.println("TransactionDebug: " + Thread.currentThread().getName() + " Transaction: " + ancestrialString() + " : " +  s);
117	    }
118	
119	    public String toString() {
120	        return "Transaction: " + transactionNumber + " parent = " + parent;
121	    }
122	
123	    public Transaction getParent() {
124	        return parent;
125	    }
126	
127	    private static boolean globalLockHeld() {
128	        return ((global_lock.get() & 1) != 0);
129	    }
130	
131	    private static boolean globalLockFree() {
132	        return !globalLockHeld();
133	    }
134	
135	    public boolean isTopLevelTransaction() {
136	        if (parent == null)
137	            return true;
138	        else return false;
139	    }
140	
141	    private static int waitForGlobalLock() {
142	        int temp = global_lock.get();
143	        while ((temp & 1) != 0)
144	            temp = global_lock.get();
145	        return temp;
146	    }
147	
148	    private static boolean getGlobalLock(int i) {
149	        if (( i & 1) == 0)
150	            return global_lock.compareAndSet(i, i+1);
151	        else throw new RuntimeException(Thread.currentThread().getName() + "Tried to get an already held lock");
152	    }
153	
154	    private static boolean releaseGlobalLock(int i) {
155	        if ((i & 1) != 0)
156	            return global_lock.compareAndSet(i, i+1);
157	        else throw new RuntimeException(Thread.currentThread().getName() + "Tried to release unheld lock");
158	    }
159	
160	    private static int snapshotGlobalLock() {
161	        int time = global_lock.get();
162	        while ((time & 1) != 0)
163	            time = global_lock.get();
164	        return time;
165	    }
166	
167	    private Transaction(Transaction parent) {
168	        this.parent = parent;
169	        this.snapshot = new AtomicInteger(parent.snapshot.get());
170	        this.reads = new Hashtable<Object, Any>();
171	        this.writes = new Hashtable<Object, Any>();
172	        this.topLevelTransaction = parent.topLevelTransaction;
173	        this.transactionNumber = counter.getAndIncrement();
174	    }
175	
176	    private Transaction(int snapshot) {
177	        this.parent = null;
178	        this.snapshot = new AtomicInteger(snapshot);
179	        this.reads = new Hashtable<Object, Any>();
180	        this.writes = new Hashtable<Object, Any>();
181	        this.topLevelTransaction = this;
182	        this.transactionNumber = counter.getAndIncrement();
183	    }        
184	
185	    /** Abandons this transaction, whose read failed: the block that began it starts again. */
186	    private void TXAbort() {
187	        if (debug) debug("TXAbort");
188	        throw new TransactionAbortException(this);
189	    }
190	
191	    public static Transaction TXBegin(Transaction parent) {
192	        Transaction result;
193	        if (parent == null) {
194	            result = new Transaction(snapshotGlobalLock());
195	        } else {
196	            result = new Transaction(parent);
197	            //throw new RuntimeException(Thread.currentThread().getName() + ": Only single level transactions for now");
198	        }
199	        if (debug) result.debug("TXBegin:");
200	        return result;
201	    }
202	
203	    private Any AncestrialWrite(Object v) {
204	        if (writes.containsKey(v))
205	            return writes.get(v);
206	        else if (parent == null)
207	            return null;
208	        else return parent.AncestrialWrite(v);
209	    }
210	
211	    public Any TXRead(MutableFValue v) {
212	        return TXReadLocation(v);
213	    }
214	
215	    /** A read of element index of a compiled array store's array; null where the element holds nothing. */
216	    public Any TXReadSlot(Object[] array, int index) {
217	        return TXReadLocation(new Slot(array, index));
218	    }
219	
220	    /**
221	     * A read of a location.  A read of this transaction's own write is no read of the committed state
222	     * and records nothing.  Any other read is recorded with what it saw, an ancestor's write or the
223	     * committed value, for the validation to compare; an element that held nothing is recorded as
224	     * EMPTY.  The threads of one block share its sets, so the read and its record are one step under
225	     * the read set's lock, which a validation holds while it iterates.  No thread waits for the global
226	     * lock while it holds a set's lock, since a commit takes the sets' locks while it holds the global one.
227	     */
228	    private Any TXReadLocation(Object v) {
229	        Any own = writes.get(v);
230	        if (own != null) {
231	            if (debug) debug("TXRead: v = " + v + " own val = " + own);
232	            return own;
233	        }
234	        while (true) {
235	            if (snapshot.get() != global_lock.get())
236	                snapshot.set(TXValidate());
237	            synchronized (reads) {
238	                Any val = (parent == null) ? null : parent.AncestrialWrite(v);
239	                if (val == null)
240	                    val = committedValue(v);
241	                if (snapshot.get() != global_lock.get())
242	                    continue;           // a commit began meanwhile: validate, and read again
243	                if (debug) debug("TXRead: v = " + v + " val = " + val);
244	                reads.put(v, val == null ? EMPTY : val);
245	                return val;             // null for an element that holds nothing yet: the store refuses the read
246	            }
247	        }
248	    }
249	
250	    /**
251	     * Compares each read of this transaction with what the location holds now for it: the write of
252	     * the nearest ancestor that wrote it, else the committed value.  A read that differs abandons
253	     * this transaction.
254	     */
255	    private void validateReads() {
256	        synchronized (reads) {
257	            for (Map.Entry<Object,Any> entry : reads.entrySet()) {
258	                Object key = entry.getKey();
259	                Any val = entry.getValue();
260	                Any now = (parent == null) ? null : parent.AncestrialWrite(key);
261	                if (now == null)
262	                    now = committedValue(key);
263	                if (debug) debug("TXValidate: key = " + key + " val = " + val + " now = " + now);
264	                if (now != (val == EMPTY ? null : val))
265	                    TXAbort();
266	            }
267	        }
268	    }
269	
270	    /**
271	     * Validates this transaction and each of its ancestors at one time of the global lock, and answers
272	     * that time.  A nested transaction runs on its ancestors' reads too, so a stale read of an ancestor
273	     * abandons that ancestor: the abort names it, and passes through the nested blocks' handlers.
274	     */
275	    public int TXValidate() {
276	        while (true) {
277	            int time = waitForGlobalLock();
278	            if (debug) debug("TXValidate: time = " + time);
279	            for (Transaction t = this; t != null; t = t.parent)
280	                t.validateReads();
281	            if (time == global_lock.get())
282	                return time;
283	        }
284	    }
285	
286	    public void TXWrite(MutableFValue v, Any f) {
287	        if (debug) debug("TXWrite: v = " + v + " f = " + f + " reads.getValue = " + reads.get(v) + " writes.getValue = " + writes.get(v));
288	        writes.put(v, f);
289	    }
290	
291	    /** A write of element index of a compiled array store's array, which the commit stores. */
292	    public void TXWriteSlot(Object[] array, int index, Any f) {
293	        Slot v = new Slot(array, index);
294	        if (debug) debug("TXWriteSlot: v = " + v + " f = " + f);
295	        writes.put(v, f);
296	    }
297	    
298	    /**
299	     * Commits.  A top-level transaction stores its writes; one that wrote nothing has nothing to do.
300	     * A nested transaction hands its parent its reads, also where it wrote nothing, and its writes.
301	     */
302	    public void TXCommit() {
303	        if (debug) debug("TXCommit: reads = " + reads + " writers = " + writes);
304	        if (parent == null && writes.isEmpty())
305	            return;
306	        handOver(true);
307	    }
308	
309	    /**
310	     * Ends a transaction whose block an exception leaves.  Its writes are dropped with it.  The exception
311	     * was thrown on what a nested transaction read, so the parent takes those reads and answers for them
312	     * at its own commit; where they no longer hold, this aborts, and the block starts again.
313	     */
314	    void TXLeave() {
315	        if (debug) debug("TXLeave: reads = " + reads + " writers = " + writes);
316	        if (parent != null)
317	            handOver(false);
318	    }
319	
320	    /** Under the global lock, taken at a time at which every read holds: the reads, and the writes if asked, go to the parent, or the writes to their locations. */
321	    private void handOver(boolean withWrites) {
322	        int time = snapshot.get();
323	
324	        while (! getGlobalLock(time)) {
325	            time = TXValidate();
326	            if (debug) debug("TXCommitFail: time " + time);
327	            snapshot.set(time);
328	        }
329	
330	        try {
331	            if (parent == null) {
332	                synchronized (writes) {
333	                    for (Map.Entry<Object,Any> entry : writes.entrySet()) {
334	                        Object key = entry.getKey();
335	                        Any val = entry.getValue();
336	                        if (debug) debug("TXCommitting:  time = " + time + " key = " + key + " val = " + val);
337	                        commitValue(key, val);
338	                    }
339	                }
340	            } else {
341	                synchronized (reads) {
342	                    for (Map.Entry<Object,Any> entry : reads.entrySet()) {
343	                        Object key = entry.getKey();
344	                        Any val = entry.getValue();
345	
346	                        // This is subtle.  If the child read a value written by a grandparent, then it has to go in the
347	                        // the parent's read set, because otherwise a cousin transaction could update the value written
348	                        // in the grandparent and the parent transaction wouldn't know to abort.
349	                        if (parent.writes.get(key) == null) {
350	                            parent.reads.put(key, val);
351	                            if (debug) debug("TXCommitting: read to parent without ancestrial write: snapshot = " + snapshot + " time = " + time + " key = " + key + " val = " + val);
352	                        }
353	                    }
354	                }
355	
356	                if (withWrites) {
357	                    synchronized (writes) {
358	                        for (Map.Entry<Object,Any> entry : writes.entrySet()) {
359	                            Object key = entry.getKey();
360	                            Any val = entry.getValue();
361	                            parent.writes.put(key, val);
362	                            if (debug) debug("TXCommitting: write to parent: snapshot = " + snapshot.get() + " time = " + time + " key = " + key + " val = " + val);
363	                        }
364	                    }
365	                }
366	            }
367	        } finally {
368	            if (! releaseGlobalLock(time+1))
369	                throw new RuntimeException("Who messed with a committing transaction?");
370	        }
371	    }
372	
373	}

